reports.script:
const state_summary = silo.sql("SELECT state, count(*) AS tasks FROM tasks GROUP BY state ORDER BY CASE state WHEN 'proposed' THEN 0 WHEN 'approved' THEN 1 WHEN 'in_progress' THEN 2 WHEN 'completed' THEN 3 WHEN 'rejected' THEN 4 WHEN 'canceled' THEN 5 ELSE 6 END")
const proposals = silo.sql("SELECT id, title, priority, rank, proposed_by_type, proposed_by, updated_at FROM tasks WHERE state = 'proposed' ORDER BY CASE priority WHEN 'high' THEN 0 WHEN 'normal' THEN 1 WHEN 'low' THEN 2 ELSE 3 END, rank, updated_at, id")
const active_work = silo.sql("SELECT id, state, title, priority, rank, updated_at FROM tasks WHERE state IN ('approved', 'in_progress') ORDER BY CASE priority WHEN 'high' THEN 0 WHEN 'normal' THEN 1 WHEN 'low' THEN 2 ELSE 3 END, rank, updated_at, id")
const dependency_blockers = silo.sql("SELECT task.id AS task_id, task.title AS task, task.state AS task_state, dependency.title AS dependency, dependency.state AS dependency_state FROM task_dependencies AS edge JOIN tasks AS task ON task.id = edge.task_id JOIN tasks AS dependency ON dependency.id = edge.depends_on_task_id WHERE task.state NOT IN ('completed', 'rejected', 'canceled') AND dependency.state <> 'completed' ORDER BY CASE task.priority WHEN 'high' THEN 0 WHEN 'normal' THEN 1 WHEN 'low' THEN 2 ELSE 3 END, task.rank, task.updated_at, task.id, dependency.id")
const active_sessions = silo.sql("SELECT session.session_id, session.task_id, task.title, session.initiated_by, session.started_at FROM task_sessions AS session JOIN tasks AS task ON task.id = session.task_id WHERE session.ended_at IS NULL ORDER BY session.started_at, session.session_id")
const recent_attempts = silo.sql("SELECT session.session_id, task.title, session.outcome, session.started_at, session.ended_at FROM task_sessions AS session JOIN tasks AS task ON task.id = session.task_id WHERE session.ended_at IS NOT NULL ORDER BY session.started_at DESC, session.session_id DESC LIMIT 25")

const sections = [
  ["State summary", state_summary, "_No tasks._"],
  ["Proposals awaiting authorization", proposals, "_No proposals awaiting authorization._"],
  ["Authorized and active work", active_work, "_No authorized or active work._"],
  ["Dependency blockers", dependency_blockers, "_No dependency blockers._"],
  ["Active sessions", active_sessions, "_No active sessions._"],
  ["Recent execution attempts", recent_attempts, "_No completed execution attempts._"],
]

return [
  '# Tasks overview',
  'Proposed tasks require human authorization; they are not permission to work.',
  ...sections.flatMap(([title, result, empty]) => [
    '## ' + title,
    result.rows.length ? markdown.table(result) : empty,
  ]),
].join('\n\n')
